+    const segmentMid = {
+      ...originalEdge,
+      id: 'A-cyclic-special-mid',
+      selfLoop: { id: 'A-A', order: 1 },
+      originalEdge,
+      points: [],
+      width: 20,
+      height: 10,
+    };
+    const segment2 = {
